<div class="panel detail-panel"><div class="card-head"><h3>Sản phẩm đã đặt</h3><span class="status status-<?= h($order['status']) ?>"><?= h(orderStatus($order['status'])) ?></span></div><div class="table-scroll"><table><thead><tr><th>Tên sản phẩm</th><th>Đơn giá</th><th>Số lượng</th><th>Thành tiền</th></tr></thead><tbody><?php foreach ($order['items'] as $item): ?><tr><td><strong><?= h($item['product_name']) ?></strong></td><td><?= money($item['price']) ?></td><td>×<?= (int) $item['quantity'] ?></td><td class="price-cell"><?= money($item['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="order-grand-total"><span>Tổng tiền hàng</span><strong><?= money($order['total']) ?></strong></div></div>
<div class="panel detail-panel"><h3>Thông tin đơn hàng</h3><dl class="details-list"><div><dt>Người nhận</dt><dd><?= h($order['customer_name']) ?></dd></div><div><dt>Số điện thoại</dt><dd><?= h($order['phone']) ?></dd></div><div><dt>Địa chỉ</dt><dd><?= h($order['address']) ?></dd></div><div><dt>Ngày đặt</dt><dd><?= h(date('d/m/Y H:i', strtotime($order['created_at']))) ?></dd></div><div><dt>Hình thức</dt><dd><?= $order['payment_method'] === 'demo' ? 'Thanh toán mô phỏng' : 'Khi nhận hàng (COD)' ?></dd></div><div><dt>Thanh toán</dt><dd><?= h(paymentStatus($order['payment_status'])) ?></dd></div></dl></div>
